package dev.photohouse.connected

import android.Manifest
import android.app.NotificationManager
import android.os.Build
import androidx.lifecycle.Lifecycle
import androidx.test.core.app.ActivityScenario
import androidx.test.platform.app.InstrumentationRegistry
import dev.photohouse.connected.core.*
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeout
import org.junit.Assert.*
import org.junit.Test
import java.io.ByteArrayInputStream

/** Real service/Activity lifecycle; generated bytes and in-memory API only. Emulator QA only. */
class BackgroundUploadForegroundTest {
    private class UploadApi : PhotoHouseApi by GeneratedMemoirReaderApi() {
        override val uploadEnabled = true
        val secondChunk = CompletableDeferred<Unit>()
        val releaseSecond = CompletableDeferred<Unit>()
        var creates = 0
        var reads = 0
        var completes = 0
        var received = 0L
        var size = 0L
        var requestId: String? = null
        val offsets = mutableListOf<Long>()
        private fun snapshot(done: Boolean = false) = UploadSession("a".repeat(32), size, received,
            4*1024*1024, if (done) "complete" else "uploading", if (done) "901" else null,
            "family", if (done) "automatic" else null, if (done) "family" else null)
        override suspend fun createUploadSession(token: Bearer, request: UploadSessionRequest): UploadSession {
            creates++; size = request.bytes; requestId = request.requestId
            return snapshot()
        }
        override suspend fun uploadSession(token: Bearer, uploadId: String): UploadSession { reads++;return snapshot() }
        override suspend fun uploadChunk(token: Bearer, uploadId: String, offset: Long, chunk: ByteArray, sha256: String): UploadSession {
            assertEquals(received, offset)
            if (offset == 4L*1024*1024) { secondChunk.complete(Unit);releaseSecond.await() }
            offsets += offset;received += chunk.size
            return snapshot()
        }
        override suspend fun completeUploadSession(token: Bearer, uploadId: String): UploadSession {
            assertEquals(size, received);completes++;return snapshot(true)
        }
    }

    private fun main(block: () -> Unit) = InstrumentationRegistry.getInstrumentation().runOnMainSync(block)
    private fun waitFor(predicate: () -> Boolean) {
        val deadline = System.currentTimeMillis() + 20000
        while (true) {
            var ready = false;main { ready = predicate() }
            if (ready) return
            check(System.currentTimeMillis() < deadline) { "Synthetic upload condition timed out" }
            Thread.sleep(50)
        }
    }

    @Test fun stoppedActivityRetainsForegroundUploadAndPrivateUiIsCovered() = exercise(false)
    @Test fun notificationPauseThenExplicitResumeReusesServerOffset() = exercise(true)
    @Test fun staleNotificationPauseCannotCancelNewerResume() = exercise(false, stalePause = true)

    private fun exercise(pause: Boolean, stalePause: Boolean = false) {
        val instrumentation = InstrumentationRegistry.getInstrumentation()
        val context = instrumentation.targetContext
        check(context.packageName == "dev.photohouse.connected.qa")
        check(Build.HARDWARE in setOf("ranchu", "goldfish"))
        if (Build.VERSION.SDK_INT >= 33) instrumentation.uiAutomation.grantRuntimePermission(context.packageName, Manifest.permission.POST_NOTIFICATIONS)
        val api = UploadApi()
        val bytes = ByteArray(8*1024*1024+13) { (it % 251).toByte() }
        val source = BatchUploadSource("synthetic.mp4",bytes.size.toLong(),UploadKind.VIDEO,{ByteArrayInputStream(bytes)},"synthetic:video")
        lateinit var store: ConnectedStore
        var initialized = false
        var scenario: ActivityScenario<MainActivity>? = null
        try {
            main {
                store = ConnectedStore(api, PhoneUploadRuntime.scope,
                    batchPersistence = InMemoryUploadQueuePersistence(), batchSource = { source })
                initialized = true
                store.authenticate("+12025550123","synthetic-password-only")
            }
            waitFor { store.state.value.session != null && !store.state.value.busy }
            main { PhoneUploadRuntime.installQaStore(store) }
            val activity = ActivityScenario.launch(MainActivity::class.java)
            scenario = activity
            main {
                store.batchUploads!!.enqueue(listOf(source),"family")
                assertTrue(BatchUploadForegroundRequests.start(context,store,BatchUploadCommand.RESUME))
            }
            runBlocking { withTimeout(20000) { api.secondChunk.await() } }
            val manager = context.getSystemService(NotificationManager::class.java)
            waitFor { manager.activeNotifications.any { it.id == 3101 } }
            if (!pause) {
                activity.recreate()
                waitFor { !store.state.value.covered && !store.state.value.busy }
                main { assertTrue(store.backgroundBatchUploadsActive());assertTrue(store.batchUploads!!.running) }
            }
            if (stalePause) {
                val oldPause = manager.activeNotifications.single { it.id == 3101 }.notification.actions.single().actionIntent
                main { assertTrue(BatchUploadForegroundRequests.start(context,store,BatchUploadCommand.RESUME)) }
                oldPause.send()
            }
            activity.moveToState(Lifecycle.State.CREATED)
            main { assertTrue(store.state.value.covered);assertTrue(store.backgroundBatchUploadsActive()) }
            if (pause) {
                manager.activeNotifications.single { it.id == 3101 }.notification.actions.single().actionIntent.send()
                waitFor { !store.backgroundBatchUploadsActive() && !store.batchUploads!!.running }
                main { assertEquals(4L*1024*1024,store.batchUploads!!.state.value.single().record.offset) }
                activity.moveToState(Lifecycle.State.RESUMED)
                waitFor { !store.state.value.covered && !store.state.value.busy }
                api.releaseSecond.complete(Unit)
                main { assertTrue(BatchUploadForegroundRequests.start(context,store,BatchUploadCommand.RESUME)) }
            } else api.releaseSecond.complete(Unit)
            waitFor { store.batchUploads!!.state.value.single().record.status == "complete" }
            waitFor { !store.backgroundBatchUploadsActive() }
            assertEquals(1,api.creates);assertEquals(1,api.completes)
            assertEquals(listOf(0L,4L*1024*1024,8L*1024*1024),api.offsets)
            assertEquals(bytes.size.toLong(),api.received)
            if (pause) assertTrue(api.reads >= 1)
        } finally {
            main { if (initialized) store.endBackgroundBatchUploads() }
            if (initialized) waitFor { context.getSystemService(NotificationManager::class.java).activeNotifications.none { it.id == 3101 } }
            context.getSystemService(NotificationManager::class.java).cancel(3102)
            scenario?.close()
            main { PhoneUploadRuntime.installQaStore(null) }
        }
    }
}
